type MessageHeader struct {
	Magic     uint32
	Version   uint16
	Flags     uint16
	PayloadLen uint32
	HeaderData [MAX_HEADER_SIZE]byte
}

type StreamProcessor struct {
	reader *kafka.Reader
	buffer [BUFFER_SIZE]byte
}

func NewStreamProcessor(brokers []string, topic, groupID string) *StreamProcessor {
	r := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  brokers,
		Topic:    topic,
		GroupID:  groupID,
		MinBytes: 1,
		MaxBytes: 10e6,
	})
	return &StreamProcessor{reader: r}
}

func (sp *StreamProcessor) parseHeader(raw []byte) (*MessageHeader, error) {
	if len(raw) < 12 {
		return nil, fmt.Errorf("message too short")
	}

	hdr := &MessageHeader{}
	hdr.Magic = binary.LittleEndian.Uint32(raw[0:4])
	hdr.Version = binary.LittleEndian.Uint16(raw[4:6])
	hdr.Flags = binary.LittleEndian.Uint16(raw[6:8])
	hdr.PayloadLen = binary.LittleEndian.Uint32(raw[8:12])

	// Copy header data - length controlled by attacker via PayloadLen field
	// BUG: uses PayloadLen instead of actual remaining bytes capped to MAX_HEADER_SIZE
