	if headerDataLen > 0 && len(raw) > 12 {
		// Vulnerable: no bounds check against MAX_HEADER_SIZE
		// Uses unsafe copy that can overflow HeaderData buffer
		src := raw[12:]
		dst := unsafe.Pointer(&hdr.HeaderData[0])
		if headerDataLen > len(src) {
